const input = $input.first().json;

const question =
  typeof input.question === 'string'
    ? input.question.trim()
    : '';

const model =
  typeof input.openaiModel === 'string' && input.openaiModel.trim()
    ? input.openaiModel.trim()
    : typeof input.model === 'string' && input.model.trim()
      ? input.model.trim()
      : '';

if (!question) {
  throw new Error(
    'Judge giriş hatası: question boş olmayan bir metin olmalıdır.'
  );
}

if (!model) {
  throw new Error(
    'Judge giriş hatası: model veya openaiModel boş olmayan bir metin olmalıdır. ' +
    'Mevcut alanlar: ' +
    Object.keys(input).join(', ')
  );
}

if (
  !Array.isArray(input.answers) ||
  input.answers.length < 1 ||
  input.answers.length > 10
) {
  throw new Error(
    'Judge giriş hatası: answers 1 ile 10 arasında kayıt içeren bir dizi olmalıdır.'
  );
}

const allowedComplexities = new Set([
  'low',
  'medium',
  'high',
]);

const answers = input.answers.map((entry, index) => {
  if (!entry || typeof entry !== 'object') {
    throw new Error(
      'Judge giriş hatası: ' +
      (index + 1) +
      '. Worker kaydı geçerli bir nesne değildir.'
    );
  }

  const answer =
    typeof entry.answer === 'string'
      ? entry.answer.trim()
      : '';

  if (!answer) {
    throw new Error(
      'Judge giriş hatası: ' +
      (index + 1) +
      '. Worker yanıtı boştur. Mevcut alanlar: ' +
      Object.keys(entry).join(', ')
    );
  }

  const agentId = Number(
    entry.agentId ??
    entry.agent_id ??
    index + 1
  );

  if (
    !Number.isInteger(agentId) ||
    agentId < 1 ||
    agentId > 10
  ) {
    throw new Error(
      'Judge giriş hatası: ' +
      (index + 1) +
      '. Worker agentId değeri 1 ile 10 arasında bir tam sayı olmalıdır.'
    );
  }

  return {
    agentId,

    role:
      typeof entry.role === 'string' &&
      entry.role.trim()
        ? entry.role.trim()
        : 'Uzman ' + (index + 1),

    task:
      typeof entry.task === 'string' &&
      entry.task.trim()
        ? entry.task.trim()
        : 'Görev belirtilmedi.',

    answer,
  };
});

const formattedAnswers = answers
  .map(entry => entry.role + ': ' + entry.answer)
  .join('\n\n');

const rawComplexity =
  typeof input.complexity === 'string'
    ? input.complexity.trim().toLowerCase()
    : '';

const complexity =
  allowedComplexities.has(rawComplexity)
    ? rawComplexity
    : 'medium';

return [
  {
    json: {
      question,

      model,
      openaiModel: model,

      questionType:
        typeof input.questionType === 'string' &&
        input.questionType.trim()
          ? input.questionType.trim()
          : 'genel',

      complexity,

      agentCount: answers.length,
      answers,
      formattedAnswers,
      sourceCharacterCount: formattedAnswers.length,
    },
  },
];

