const response = $input.first().json;
const source = $('Validate and Format Judge Input').first().json;

if (response.status === 'incomplete') {
  const reason = response.incomplete_details?.reason;
  throw new Error(reason === 'max_output_tokens'
    ? 'Nihai sentez çıktı sınırına ulaştı.'
    : 'Nihai sentez tamamlanmadan durdu.');
}

// OpenAI Responses API içindeki output_text alanını bul.
const content = response?.output
  ?.flatMap((item) =>
    Array.isArray(item?.content) ? item.content : []
  )
  ?.find((item) => item?.type === 'output_text')
  ?.text;

if (typeof content !== 'string' || !content.trim()) {
  throw new Error(
    'Nihai sentez hatası: OpenAI response.output içinde output_text döndürmedi.'
  );
}

let synthesized;

try {
  synthesized = JSON.parse(content);
} catch (error) {
  throw new Error(
    'Nihai sentez ayrıştırma hatası: OpenAI geçerli JSON döndürmedi (' +
    error.message +
    ').'
  );
}

const finalAnswer =
  typeof synthesized?.final_answer === 'string'
    ? synthesized.final_answer.trim()
    : '';

if (!finalAnswer) {
  throw new Error(
    'Judge nihai yanıt hatası: final_answer boştur.'
  );
}

if (
  !Array.isArray(source.answers) ||
  source.answers.length !== source.agentCount
) {
  throw new Error(
    'Judge çıktı hatası: Worker yanıt sayısı agentCount ile eşleşmiyor.'
  );
}

const model =
  typeof source.openaiModel === 'string' &&
  source.openaiModel.trim()
    ? source.openaiModel.trim()
    : typeof source.model === 'string' &&
        source.model.trim()
      ? source.model.trim()
      : 'gpt-5-mini';

return [
  {
    json: {
      question: source.question,
      model,
      openaiModel: model,

      questionType:
        source.questionType ?? 'genel',

      complexity:
        source.complexity ?? 'medium',

      agentCount:
        source.agentCount,

      answers:
        source.answers,

      sourceCharacterCount:
        source.sourceCharacterCount,

      finalAnswer,
      diagram: synthesized.diagram,
      displayAnswer: finalAnswer,
      summaryPoints: [],
    },
  },
];
